input.Body:
=const response = flow.step('create').actionResponse;
const request = flow.step('create').actionRequest;
const title = 'Employee Create Failure Notification';
let body = '';

function parseArray(key, val) {
  if (key === null) return;
  if (val.length === 0) return;
  // Remove the recursive check — val is already the array here
  val.forEach((v, i) => {
    if (v !== null && typeof v !== 'object') {
      body += `<tr><td><strong>${key} - ${i}</strong></td><td>${v}</td></tr>`;
    }
  });
}

function parseObject(value) {
  if (value === null) return;
  Object.entries(value).forEach(([key, val]) => {
    if (Array.isArray(val)) {
      parseArray(key, val);
    } else if (val !== null && typeof val === 'object') {
      parseObject(val);
    } else {
      body += `<tr><td><strong>${key}</strong></td><td>${val}</td></tr>`;
    }
  });
}

body += `<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:14px;color:#222;">
  <tr>
    <td style="padding:12px 0;font-size:18px;font-weight:bold;">
      ${title}
    </td>
  </tr>
</table>


<table role="presentation" cellpadding="8" cellspacing="0" border="1" width="100%" style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:14px;color:#222;border:1px solid #ccc;">
  <tr style="background-color:#f5f5f5;font-weight:bold;">
    <td colspan="2">Request Details</td>
  </tr>`;

Object.entries(request).forEach(([key, val]) => {
  body += `<tr><td><strong>${key}</strong></td><td>${val}</td></tr>`;
});

body += `</table>

<br>

<table role="presentation" cellpadding="8" cellspacing="0" border="1" width="100%" style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:14px;color:#222;border:1px solid #ccc;">
  <tr style="background-color:#f5f5f5;font-weight:bold;">
    <td colspan="2">Response Details</td>
  </tr>`;

Object.entries(response.result).forEach(([key, val]) => {
  if (Array.isArray(val)) {
    parseArray(key, val);
  }

  if (val !== null && typeof val === 'object') {
    parseObject(val);
  }

  body += `<tr><td><strong>${key}</strong></td><td>${val}</td></tr>`;
});

body += '</table>';

return body;

